package party.lemons.biomemakeover.client.model;
import net.minecraft.client.model.EntityModel;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.util.Mth;import party.lemons.biomemakeover.client.render.MothRenderState;
public final class MothModel extends EntityModel<MothRenderState>{private final ModelPart body,head,rw,lw;public MothModel(ModelPart root){super(root);body=root.getChild("moth");head=body.getChild("head");rw=body.getChild("wing_right");lw=body.getChild("wing_left");}
 public static LayerDefinition createBodyLayer(){MeshDefinition m=new MeshDefinition();PartDefinition r=m.getRoot();PartDefinition b=r.addOrReplaceChild("moth",CubeListBuilder.create(),PartPose.offset(0,13,-1));b.addOrReplaceChild("abdomen",CubeListBuilder.create().texOffs(0,18).addBox(-4,-5.5F,-2.5F,6,8,6),PartPose.offsetAndRotation(1,7.5F,4.5F,.7854F,0,0));b.addOrReplaceChild("thorax",CubeListBuilder.create().texOffs(0,0).addBox(-4,-5,-4,8,10,8),PartPose.offsetAndRotation(0,-.3827F,-.0761F,.3927F,0,0));b.addOrReplaceChild("legs",CubeListBuilder.create().texOffs(22,30).addBox(-.5F,-3.5F,-4.5F,0,7,6).texOffs(32,5).addBox(11.5F,-3.5F,-4.5F,0,7,6).texOffs(4,43).addBox(-.5F,-3.5F,1.5F,2,7,0).texOffs(0,43).addBox(9.5F,-3.5F,1.5F,2,7,0),PartPose.offsetAndRotation(-5.5F,1.5F,-3.5F,.3927F,0,0));PartDefinition h=b.addOrReplaceChild("head",CubeListBuilder.create().texOffs(24,24).addBox(-3,-5,-3.9F,6,6,6),PartPose.offset(0,-5,-2));PartDefinition hd=h.addOrReplaceChild("decoration",CubeListBuilder.create(),PartPose.offset(0,16,3));hd.addOrReplaceChild("antennae",CubeListBuilder.create().texOffs(24,18).addBox(-1.5F,-4.5F,0,3,7,0).texOffs(24,0).addBox(3.5F,-4.5F,0,3,7,0),PartPose.offsetAndRotation(-2.5F,-23.3F,-4,.3927F,0,0));b.addOrReplaceChild("wing_right",CubeListBuilder.create().texOffs(32,0).addBox(-11,-8,.6F,11,11,.01F).texOffs(34,36).addBox(-8,3,.6F,8,7,.01F),PartPose.offsetAndRotation(-1,-5,1.7F,.3927F,0,0));b.addOrReplaceChild("wing_left",CubeListBuilder.create().texOffs(0,32).addBox(0,-8,.6F,11,11,.01F).texOffs(42,18).addBox(0,3,.6F,8,7,.01F),PartPose.offsetAndRotation(1,-5,1.8F,.3927F,0,0));return LayerDefinition.create(m,64,64);}
 @Override public void setupAnim(MothRenderState s){super.setupAnim(s);head.xRot=s.xRot*Mth.DEG_TO_RAD;head.yRot=s.yRot*Mth.DEG_TO_RAD;float a=s.ageInTicks*2.1F;lw.yRot=-1+Mth.cos(a)*Mth.PI*.1F;rw.yRot=-lw.yRot;body.xRot=.1F+Mth.cos(s.ageInTicks*.18F)*Mth.PI*.025F;body.y=19-Mth.cos(s.ageInTicks*.18F)*.9F;if(s.bodyPitch>0)body.xRot=Mth.lerp(s.bodyPitch,body.xRot,3.0915928F);}
}
